'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={dashboard:'總覽 Dashboard',companies:'客戶與聯絡人',files:'檔案管理',opportunities:'業務商機',quotes:'報價單',visits:'拜訪與跟進',meetings:'會議紀錄',tasks:'任務看板',projects:'專案 Pipeline',leads:'行銷名單',campaigns:'EDM 活動',tickets:'維修工單',instruments:'儀器履歷',contracts:'保養合約',products:'庫存與料號',articles:'知識庫',settings:'設定與審計',trash:'垃圾桶'};
const NAV=[['共用',['dashboard','companies','files']],['業務',['opportunities','quotes','visits','meetings','tasks','projects']],['行銷',['leads','campaigns']],['售後維修／客服',['tickets','instruments','contracts','products','articles']],['系統',['settings','trash']]];
const DEPT_GROUPS={'業務':['共用','業務','系統'],'行銷':['共用','行銷','系統'],'維修':['共用','售後維修／客服','系統'],'客服':['共用','售後維修／客服','系統']};
const ICON={dashboard:'◈',companies:'▦',files:'▱',opportunities:'◫',quotes:'＄',visits:'◎',meetings:'▧',tasks:'✓',projects:'▤',leads:'☷',campaigns:'✉',tickets:'⚒',instruments:'◉',contracts:'▣',products:'▥',articles:'✎',settings:'⚙',trash:'⌫'};
const BOARDS=['opportunities','projects','tasks','tickets','quotes'];
const entityLabels={companies:'公司',contacts:'聯絡人',opportunities:'商機',projects:'專案',tasks:'任務',visits:'拜訪紀錄',meetings:'會議紀錄',milestones:'里程碑',files:'檔案',trash:'垃圾桶',instruments:'儀器',contracts:'合約',tickets:'工單',quotes:'報價單',products:'料號',stockmoves:'庫存異動',articles:'知識文章',campaigns:'EDM',leads:'名單'};
let user,csrf,data,page='dashboard',filter='',aiVisible=false,busy=false,viewDept='',loginBrand=null;
const brand=()=>data?.meta?.settings||loginBrand||{brandMark:'GAME',brandName:'精冠智能',brandTagline:'工作平台'};
const brandHTML=()=>{const b=brand();return `<div class="brand">${b.brandMark==='GAME'?'G<span>A</span>ME':esc(b.brandMark)}<small>${esc(b.brandName)} · ${esc(b.brandTagline)}</small></div>`;};
const entityOf=p=>p==='leads'?'contacts':p;
const write=()=>user.role!=='viewer';
const money=v=>Number(v||0).toLocaleString('zh-TW',{maximumFractionDigits:0});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei'}).format(new Date());
const nameOf=(type,id)=>data?.[type]?.find(x=>x.id===id)?.name||'—';
const recordOf=(type,id)=>data[type]?.find(x=>x.id===id);
async function api(path,options={}) {const res=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf||'',...options.headers},body:options.body!==undefined?JSON.stringify(options.body):undefined});const b=await res.json();if(!res.ok){if(res.status===401&&user){user=null;login();}throw new Error(b.error||'操作失敗');}return b;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000);}
async function login(){ try{loginBrand=await (await fetch('/api/brand')).json();document.title=loginBrand.brandName+'｜'+loginBrand.brandTagline;}catch{} $('#app').innerHTML=`<div class="login"><div class="loginpanel">${brandHTML()}<h1 style="margin-top:26px">讓每一次合作，持續前進。</h1><p class="muted">業務 × 行銷 × 維修 × 客服 × AI 助理</p><form id="loginform"><label class="field">帳號<input name="email" type="email" autocomplete="username" required placeholder="你的登入 Email"></label><label class="field">密碼<input name="password" type="password" autocomplete="current-password" required></label><div class="error" id="loginerror"></div><button class="primary">登入工作平台 →</button></form><p class="notice">請使用管理員提供的帳號登入。</p></div></div>`;$('#loginform').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const b=await api('/api/login',{method:'POST',body:Object.fromEntries(new FormData(e.target))});user=b.user;csrf=b.csrf;await refresh();}catch(e){$('#loginerror').textContent=e.message;}finally{button.disabled=false;}};}
async function refresh(){data=await api('/api/data');if(!viewDept)viewDept=user.role==='admin'?'全部':(user.department&&DEPT_GROUPS[user.department]?user.department:'全部');document.title=brand().brandName+'｜'+brand().brandTagline;render();}
function render(){
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar">${brandHTML()}<nav class="nav">${NAV.filter(([g])=>viewDept==='全部'||(DEPT_GROUPS[viewDept]||[]).includes(g)).map(([g,pages])=>`<div class="navlabel">${esc(g)}</div>${pages.filter(k=>k!=='trash'||user.role==='admin').map(k=>`<button data-page="${k}" class="${k===page?'active':''}"><span>${ICON[k]}</span>${labels[k]}</button>`).join('')}`).join('')}</nav><div class="sidebarfooter">把關係轉為商機<br>把承諾轉為交付<p><button type="button" id="versionbtn" class="versionbtn" title="查看版本紀錄">CRM · V${esc((window.CHANGELOG||[{version:'?'}])[0].version)}</button></p></div></aside><main class="main"><header class="topbar"><input id="search" placeholder="⌕ 搜尋客戶、專案與紀錄…" aria-label="全文搜尋"><div class="account">${user.role==='admin'?`<label class="viewas">部門視角<select id="viewdept">${['全部',...Object.keys(DEPT_GROUPS)].map(d=>`<option ${d===viewDept?'selected':''}>${d}</option>`).join('')}</select></label>`:user.department?`<span class="badge">${esc(user.department)}部門</span>`:''}<button class="mobile-ai" id="toggleai">✦ AI</button><span class="avatar">${esc(user.name[0])}</span><span class="username">${esc(user.name)}<small style="display:block">${{admin:'管理員',member:'協作成員',viewer:'唯讀成員'}[user.role]}</small></span><button id="logout">登出</button></div></header><section class="content"><div class="heading"><div><div class="eyebrow">${esc(brand().brandMark)} WORKSPACE / ${esc(page)}</div><h1>${labels[page]}</h1><p class="muted">${page==='dashboard'?'掌握每一個商機，推進每一個專案。':page==='trash'?'刪除的資料會保留 '+(data.meta.trashDays||90)+' 天，期滿後永久移除。':'把資訊與下一步，留在同一個工作空間。'}</p></div><div class="buttons">${write()&&!['settings','trash'].includes(page)?`<button id="add" class="primary">＋ ${page==='dashboard'?(['維修','客服'].includes(viewDept)?'新增工單':viewDept==='行銷'?'新增名單':'新增商機'):'新增'+(entityLabels[page]||'資料')}</button>`:''}<button id="reload">↻</button></div></div><div id="view"></div></section></main><aside class="ai ${aiVisible?'visible':''}"><div class="aihead"><span class="spark">✦</span><strong>${esc(brand().brandMark)} AI 助理</strong><p class="muted" style="margin-left:40px;font-size:11px">一起討論，讓下一步更清晰。</p><button class="mobile-ai" id="closeai">關閉</button></div><div class="aimode ${data.meta.mode==='live'?'live':''}">${data.meta.mode==='demo'?'● 規則查詢模式 · 以關鍵字查詢資料，未啟用 AI。自然語言推理需設定 API 金鑰。':'● AI API 模式 · 查詢內容將傳送至 OpenAI。寫入需確認。'}</div><div class="chatlog" id="chatlog">${chatHTML()}</div><form class="aiform" id="chatform"><textarea name="message" aria-label="傳送訊息給助理" placeholder="查詢商機或討論專案風險…" maxlength="4000" required></textarea><div class="actions">${write()?'<button type="button" id="draftbtn">＋ 建立寫入草稿</button>':''}<button class="primary" id="sendchat">傳送 ↑</button></div><small>所有寫入先確認，執行後保留審計紀錄。</small></form></aside></div>`;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;filter='';render();});
 $('#versionbtn')?.addEventListener('click',showChangelog);
 $('#logout').onclick=async()=>{try{await api('/api/logout',{method:'POST',body:{}});user=null;csrf=null;login();}catch(e){toast(e.message);}};
 $('#reload').onclick=()=>refresh().catch(e=>toast(e.message));
 if($('#add'))$('#add').onclick=()=>edit(page==='dashboard'?(['維修','客服'].includes(viewDept)?'tickets':viewDept==='行銷'?'contacts':'opportunities'):entityOf(page));
 if($('#viewdept'))$('#viewdept').onchange=e=>{viewDept=e.target.value;const groups=DEPT_GROUPS[viewDept];if(groups&&!NAV.some(([g,p])=>groups.includes(g)&&p.includes(page)))page='dashboard';render();};
 $('#search').onkeydown=e=>{if(e.key==='Enter')showSearch(e.target.value);};
 if($('#toggleai'))$('#toggleai').onclick=()=>{aiVisible=true;$('.ai').classList.add('visible');};
 $('#closeai').onclick=()=>{aiVisible=false;$('.ai').classList.remove('visible');};
 if($('#draftbtn'))$('#draftbtn').onclick=()=>draftForm();
 $('#chatform').onsubmit=sendChat;bindDrafts();renderView();$('#chatlog').scrollTop=$('#chatlog').scrollHeight;
}
function chatHTML(){return `${data.chats.length?data.chats.map(c=>`<div class="bubble ${c.role==='user'?'user':''}"><span class="chatlabel">${c.role==='user'?'你':data.meta.mode==='demo'?brand().brandMark+' 查詢助理':brand().brandMark+' AI'}</span>${esc(c.content)}</div>`).join(''):`<div class="bubble"><span class="chatlabel">${esc(brand().brandMark)} 助理</span>歡迎來到跨部門協作平台。可以查詢客戶、儀器維修史、合約、庫存與報價，或輸入錯誤代碼取得排除步驟。<br><br>${data.meta.mode==='demo'?'目前使用規則式查詢，不會進行 AI 推理。':'回答會根據工具查詢結果提供來源。'}</div>`}<div class="suggestions">${(data.meta.mode==='demo'?['E-VAC-01','宜蘭精密','燈絲','風險']:['E-VAC-01 抽真空異常怎麼處理？','未來 60 天有哪些合約到期？要提醒誰續約？','哪些料號低於安全庫存？','整理宜蘭精密的客戶摘要：儀器、合約、工單、報價']).map(t=>`<button data-suggest="${esc(t)}">${esc(t.length>14?t.slice(0,14)+'…':t)}</button>`).join('')}</div>${data.drafts.filter(d=>d.status==='pending').map(d=>draftHTML(d)).join('')}`;}
function draftDescription(p){if(p.kind==='create_task')return `建立任務：${p.data.name}\n負責人：${nameOf('users',p.data.ownerId)}\n商機：${nameOf('opportunities',p.data.opportunityId)}\n專案：${nameOf('projects',p.data.projectId)}\n截止：${p.data.dueDate||'未設定'}\n內容：${p.data.description||'—'}`;return `${entityLabels[p.entity]}：${nameOf(p.entity,p.id)}\n階段：${p.beforeStage}${p.beforeOutcome?'（'+p.beforeOutcome+'）':''} → ${p.stage}${p.outcome?'（'+p.outcome+'）':''}\n${p.lossReason?'未成交原因：'+p.lossReason:''}`;}
function draftHTML(d){return `<div class="draft"><strong>✦ 待確認寫入草稿</strong><pre>${esc(draftDescription(d.payload))}</pre><button data-confirm="${d.id}" class="primary">確認並執行</button><button data-reject="${d.id}">拒絕</button></div>`;}
function bindDrafts(){document.querySelectorAll('[data-confirm],[data-reject]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/drafts/'+(b.dataset.confirm||b.dataset.reject),{method:'POST',body:{decision:b.dataset.confirm?'confirm':'reject'}});await refresh();toast(b.dataset.confirm?'已執行並保存審計紀錄':'已拒絕草稿');}catch(e){toast(e.message);b.disabled=false;}});document.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=()=>{$('#chatform textarea').value=b.dataset.suggest;$('#chatform').requestSubmit();});}
async function sendChat(e){e.preventDefault();if(busy)return;busy=true;const text=e.target.message.value;$('#sendchat').disabled=true;$('#sendchat').textContent='查詢中…';try{await api('/api/chat',{method:'POST',body:{message:text}});await refresh();}catch(e){toast(e.message);}finally{busy=false;if($('#sendchat')){$('#sendchat').disabled=false;$('#sendchat').textContent='傳送 ↑';}}}
function renderView(){const v=$('#view');if(page==='dashboard')dashboard(v);else if(BOARDS.includes(page))board(v,page);else if(page==='leads')leadsView(v);else if(page==='settings')settings(v);else if(page==='trash')trashView(v);else tableView(v,page);if(user.role==='admin'&&data.meta.fields[page]){const link=document.createElement('a');link.href='/api/export/'+page;link.className='exportlink';link.textContent='↓ 匯出 CSV';v.prepend(link);}}
function salesDashboard(v){const open=data.opportunities.filter(o=>o.stage!=='結案'),active=data.projects.filter(p=>p.stage!=='交付維運'),pending=data.tasks.filter(t=>t.stage!=='已完成'),overdue=pending.filter(t=>t.dueDate&&t.dueDate<today());
 const stats=[['進行中商機',open.length,'筆商機','◫'],['商機預估總額','NT$ '+money(open.reduce((a,o)=>a+Number(o.amount||0),0)),'未結案商機金額','↗'],['執行中專案',active.length,'筆專案','▤'],['待完成任務',pending.length,overdue.length+' 筆逾期','✓']];
 v.innerHTML=`${overdue.length?'<div class="deadlinealert">⚑ 有 '+overdue.length+' 筆逾期任務，請優先處理。</div>':''}<div class="stats">${stats.map(([title,value,note,icon])=>`<div class="stat"><span class="icon">${icon}</span><small>${title}</small><div class="value" style="${String(value).length>9?'font-size:22px':''}">${value}</div><small>${note}</small></div>`).join('')}</div><div class="split"><div class="card"><h2>業務 Pipeline <small style="float:right">${data.opportunities.length} 筆</small></h2><div class="chart">${data.meta.sales.map((s,i)=>{const n=data.opportunities.filter(o=>o.stage===s).length;return `<div class="barrow"><span>${s}</span><div class="bartrack"><div class="bar" style="width:${n?Math.max(10,n/Math.max(1,data.opportunities.length)*100):0}%"></div></div><b>${n}</b></div>`;}).join('')}</div></div><div class="card"><h2>近期任務 <small style="float:right">依截止日</small></h2>${pending.sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')).slice(0,4).map(t=>`<div class="row" data-open="tasks" data-id="${t.id}"><span class="badge ${t.priority==='高'?'high':''}">${t.priority||'中'}</span><div class="rowbody"><strong>${esc(t.name)}</strong><small>${esc(nameOf('users',t.ownerId))} · ${t.dueDate||'未設日期'}</small></div><span class="badge">${t.stage}</span></div>`).join('')||'<p class="muted">目前沒有待完成任務。</p>'}</div></div><div class="split"><div class="card"><h2>專案進度</h2>${data.projects.slice(0,4).map(p=>{const ms=data.milestones.filter(m=>m.projectId===p.id),done=ms.filter(m=>m.stage==='已完成').length;return `<div class="row" data-open="projects" data-id="${p.id}"><div class="rowbody"><strong>${esc(p.name)}</strong><small>${esc(nameOf('companies',p.companyId))} · ${p.stage}</small><div class="progress"><div style="width:${ms.length?done/ms.length*100:0}%"></div></div></div><span class="badge">${done}/${ms.length} 里程碑</span></div>`;}).join('')||'<p class="muted">成交商機可轉為專案，自動建立里程碑。</p>'}</div><div class="card"><h2>下一次跟進</h2>${data.visits.filter(r=>r.followUpAt).sort((a,b)=>a.followUpAt.localeCompare(b.followUpAt)).slice(0,4).map(r=>`<div class="row" data-open="visits" data-id="${r.id}"><span class="avatar">◎</span><div class="rowbody"><strong>${esc(r.nextStep||r.name)}</strong><small>${esc(nameOf('companies',r.companyId))}</small></div><small>${r.followUpAt.replace('T',' ')}</small></div>`).join('')||'<p class="muted">尚未設定跟進。</p>'}</div></div>`;bindOpen(v);}
function board(v,type){const stages=data.meta.stages[type];const byOwner=['tasks','tickets','quotes'].includes(type);
 const rows=data[type].filter(r=>!filter||r.product===filter||r.ownerId===filter);const DONE=['已完成','已完工','成交','未成交'];
 v.innerHTML=`<div class="toolbar"><span class="badge">${rows.length} 筆${entityLabels[type]}</span><select id="filter" aria-label="篩選"><option value="">全部${byOwner?'負責人':'產品類型'}</option>${(byOwner?data.users.map(u=>[u.id,u.name]):data.meta.products.map(p=>[p,p])).map(([id,n])=>`<option value="${esc(id)}" ${id===filter?'selected':''}>${esc(n)}</option>`).join('')}</select><small>${type==='opportunities'?'第六階段「結案」區分成交與未成交；成交後可轉專案。':type==='tickets'?'拖移卡片更新維修進度；客戶可即時看到「已收單 → 工程師出發 → 維修中 → 待料 → 已完工」。':type==='quotes'?'報價單號自動產生；成交後填入發票號碼與款項狀態。':'可拖移卡片或使用下拉選單變更階段。'}</small></div><div class="board" style="grid-template-columns:repeat(${stages.length},minmax(${stages.length>5?180:205}px,1fr))">${stages.map((s,i)=>`<div class="column" data-dropstage="${esc(s)}"><div class="coltitle"><span>${String(i+1).padStart(2,'0')} · ${s}</span><span>${rows.filter(r=>r.stage===s).length}</span></div>${rows.filter(r=>r.stage===s).map(r=>`<article class="ticket" draggable="${write()}" data-dragid="${r.id}" data-open="${type}" data-id="${r.id}"><span class="badge ${r.outcome==='成交'||r.stage==='成交'?'green':r.priority==='高'?'high':''}">${esc(r.outcome||r.product||r.kind||r.category||r.priority||'中')}</span>${type==='tickets'&&r.priority==='高'?' <span class="badge high">急件</span>':''}${r.errorCode?` <span class="badge">${esc(r.errorCode)}</span>`:''}<strong>${esc(r.name)}</strong><small>${esc(type==='tasks'?nameOf(r.projectId?'projects':'opportunities',r.projectId||r.opportunityId):nameOf('companies',r.companyId))}</small>${type==='tickets'&&r.instrumentId?`<small>◉ ${esc(nameOf('instruments',r.instrumentId).split('｜')[0])}</small>`:''}${type==='quotes'?`<small>${esc(r.quoteNo||'')}</small><p>NT$ ${money(quoteTotals(r).net)}</p>`:''}${type==='opportunities'?`<p>NT$ ${money(r.amount)}</p>`:''}${r.risks?`<small style="color:#bc795a">⚑ ${esc(r.risks)}</small>`:''}<div class="ticketbottom"><span>${esc(nameOf('users',r.ownerId))}</span><span>${(r.dueDate||r.scheduledDate)&&(r.dueDate||r.scheduledDate)<today()&&!DONE.includes(r.stage)?'⚑ 逾期 ':''}${esc(r.dueDate||r.scheduledDate||r.quoteDate||'未設日期')}</span></div>${write()?`<select data-stage="${r.id}" aria-label="${esc(r.name)}階段">${stages.map(s=>`<option ${r.stage===s?'selected':''}>${s}</option>`).join('')}</select>`:''}</article>`).join('')||'<div class="empty">暫無資料</div>'}</div>`).join('')}</div>`;
 $('#filter').onchange=e=>{filter=e.target.value;renderView();};bindOpen(v);v.querySelectorAll('[data-dragid]').forEach(card=>card.ondragstart=e=>{if(!write())return e.preventDefault();e.dataTransfer.setData('text/plain',card.dataset.dragid);e.dataTransfer.effectAllowed='move';});v.querySelectorAll('[data-dropstage]').forEach(column=>{column.ondragover=e=>{if(write()){e.preventDefault();column.classList.add('dragover');}};column.ondragleave=()=>column.classList.remove('dragover');column.ondrop=async e=>{e.preventDefault();column.classList.remove('dragover');if(!write())return;const r=recordOf(type,e.dataTransfer.getData('text/plain')),stage=column.dataset.dropstage;if(!r||r.stage===stage)return;if(type==='opportunities'&&stage==='結案')return edit(type,{...r,stage});try{await api('/api/records/'+type+'/'+r.id,{method:'PATCH',body:{stage,version:r.version}});await refresh();toast('階段已更新');}catch(error){toast(error.message);}};});v.querySelectorAll('[data-stage]').forEach(s=>{s.onclick=e=>e.stopPropagation();s.onchange=async e=>{e.stopPropagation();const r=recordOf(type,s.dataset.stage);if(type==='opportunities'&&s.value==='結案'){edit(type,{...r,stage:'結案'});s.value=r.stage;return;}try{await api(`/api/records/${type}/${r.id}`,{method:'PATCH',body:{stage:s.value,version:r.version}});await refresh();toast('階段已更新');}catch(e){toast(e.message);s.value=r.stage;}};});}
function tableView(v,type){const cols={companies:['name','industry','contacts','instCount'],visits:['name','companyId','date','method','followUpAt'],meetings:['name','companyId','date','summary'],files:['name','companyId','size','description'],instruments:['name','companyId','model','serialNo','warrantyStatus','lastService'],contracts:['name','companyId','contractType','period','usage','expiry'],products:['name','sku','category','stock','safetyStock','compatibleModels'],articles:['name','errorCode','category','models'],campaigns:['name','stage','targetGroups','recipients','openRate']}[type]||['name'];
 const headers={name:'名稱',industry:'產業',contacts:'聯絡人',instCount:'儀器',companyId:'客戶公司',date:'日期',method:'方式',followUpAt:'跟進時間',summary:'摘要',size:'檔案大小',description:'說明',model:'機型',serialNo:'序號',warrantyStatus:'保固／合約',lastService:'最近維修',contractType:'類型',period:'合約期間',usage:'巡檢／叫修使用',expiry:'到期',sku:'品號',category:'分類',stock:'目前庫存',safetyStock:'安全庫存',compatibleModels:'適用機型',errorCode:'錯誤代碼',models:'適用機型',stage:'狀態',targetGroups:'寄送分組',recipients:'收件人',openRate:'開信率／點擊率'};
 const rows=type==='products'&&filter==='low'?data.products.filter(p=>isLow(p)):data[type];
 v.innerHTML=`${type==='files'?'<p class="filehint">每份檔案上限依登入後顯示的儲存設定（本機 5 MB／雲端 3 MB）。TXT、MD、CSV、JSON、LOG 可搜尋內文；其他檔案可搜尋名稱與說明。</p>':''}${type==='products'?`<div class="toolbar"><select id="filter"><option value="">全部料號</option><option value="low" ${filter==='low'?'selected':''}>僅顯示低於安全庫存</option></select>${write()?'<button id="addmove">＋ 進出貨／領用</button>':''}<small>庫存＝期初數量＋進貨－出貨－維修領用；維修領用會自動比對儀器機型，防止領錯料。</small></div>`:''}${type==='articles'?'<p class="filehint">輸入錯誤代碼或症狀，工單頁會自動帶出對應 SOP 與過往相似案例；AI 助理也會引用這裡的內容。</p>':''}<div class="tablewrap"><table><thead><tr>${cols.map(c=>`<th>${headers[c]||c}</th>`).join('')}<th></th></tr></thead><tbody>${rows.map(r=>`<tr>${cols.map(c=>`<td>${cell(type,c,r)}</td>`).join('')}<td>${type==='files'?`<a href="/api/files/${r.id}/download">下載</a>`:`<button data-open="${type}" data-id="${r.id}">檢視 →</button>`}</td></tr>`).join('')||`<tr><td colspan="${cols.length+1}" class="empty">尚無資料，新增後即可開始協作。</td></tr>`}</tbody></table></div>`;bindOpen(v);
 if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;renderView();};if($('#addmove'))$('#addmove').onclick=()=>edit('stockmoves',{kind:'國內進貨'});}
function cell(type,c,r){
 if(c==='name')return `<button class="link" data-open="${type}" data-id="${r.id}">${esc(r.name)}</button><small style="display:block">${esc(type==='products'?r.unit||'':r.id.slice(0,8))}</small>`;
 if(['companyId'].includes(c))return esc(nameOf('companies',r.companyId));
 if(c==='contacts')return data.contacts.filter(x=>x.companyId===r.id).map(x=>esc(x.name)).join('、')||'—';
 if(c==='instCount'){const n=data.instruments.filter(x=>x.companyId===r.id).length;return n?n+' 台':'—';}
 if(c==='size')return Math.ceil(r.size/1024)+' KB';
 if(c==='lastService'){const t=data.tickets.filter(x=>x.instrumentId===r.id).sort((a,b)=>String(b.scheduledDate).localeCompare(String(a.scheduledDate)))[0];return t?`${esc(t.scheduledDate||'')}<small style="display:block">${esc(t.kind)}・${esc(t.stage)}</small>`:'—';}
 if(c==='period')return `${esc(r.startDate)} ~ ${esc(r.endDate)}`;
 if(c==='usage'){const u=contractUsage(r);return `巡檢 ${u.pmDone}/${r.inspections||0}<br>叫修 ${u.callUsed}/${r.callouts||0}`;}
 if(c==='expiry'){const d=daysTo(r.endDate);return d<0?'<span class="badge">已到期</span>':d<=60?`<span class="badge high">${d} 天後到期</span>`:`<span class="badge green">${d} 天</span>`;}
 if(c==='stock'){const n=stockOf(r.id);return `<b>${n}</b> ${isLow(r)?'<span class="badge high">低於安全庫存</span>':''}`;}
 if(c==='warrantyStatus')return `<span class="badge ${r.warrantyStatus==='過保'?'high':'green'}">${esc(r.warrantyStatus||'—')}</span>`;
 if(c==='stage')return `<span class="badge">${esc(r.stage)}</span>`;
 if(c==='recipients')return recipientsOf(r).length+' 位';
 if(c==='openRate'){const d=Number(r.delivered)||0;return d?`${pct(r.opened,d)}／${pct(r.clicked,d)}`:'—';}
 return esc(String(r[c]||'—').slice(0,150));
}
// ---------- shared calculations ----------
const pct=(a,b)=>b?(Number(a||0)/b*100).toFixed(1)+'%':'—';
const daysTo=d=>d?Math.round((Date.parse(d)-Date.parse(today()))/86400000):Infinity;
const OUT_KINDS=['國內出貨','國外出貨','維修領用'];
const signedQty=m=>{const q=Number(m.qty)||0;return m.kind==='盤點調整'?q:OUT_KINDS.includes(m.kind)?-Math.abs(q):Math.abs(q);};
function stockOf(id){const p=recordOf('products',id);return (Number(p?.openingStock)||0)+data.stockmoves.filter(m=>m.productId===id).reduce((n,m)=>n+signedQty(m),0);}
const isLow=p=>Number(p.safetyStock)>0&&stockOf(p.id)<Number(p.safetyStock);
function quoteLines(r){return String(r.items||'').split('\n').map(l=>l.split('|').map(x=>x.trim())).filter(x=>x[0]).map(([name,qty='1',unit='',price='0'])=>({name,qty:Number(qty)||0,unit,price:Number(String(price).replace(/,/g,''))||0,amount:(Number(qty)||0)*(Number(String(price).replace(/,/g,''))||0)}));}
function quoteTotals(r){const lines=quoteLines(r),subtotal=lines.reduce((a,l)=>a+l.amount,0),net=r.finalAmount!==''&&r.finalAmount!=null&&r.finalAmount!==undefined&&String(r.finalAmount).trim()!==''?Number(r.finalAmount):subtotal,tax=Math.round(net*0.05);return {lines,subtotal,net,tax,total:net+tax};}
function contractUsage(c){const t=data.tickets.filter(x=>x.contractId===c.id);return {pmDone:t.filter(x=>x.kind==='PM 巡檢'&&x.stage==='已完工').length,pmAll:t.filter(x=>x.kind==='PM 巡檢').length,callUsed:t.filter(x=>x.kind==='叫修').length};}
const splitList=v=>String(v||'').split(/[、,，;；]/).map(x=>x.trim()).filter(Boolean);
function recipientsOf(c){const target=splitList(c.targetGroups),ex=splitList(c.excludeGroups);return data.contacts.filter(x=>x.email&&x.subscription!=='已取消訂閱'&&splitList(x.groups).some(g=>target.includes(g))&&!splitList(x.groups).some(g=>ex.includes(g)));}
function bars(rows){const max=Math.max(1,...rows.map(r=>r[1])),wide=rows.some(r=>r[2]);return `<div class="chart">${rows.map(([k,n,label])=>`<div class="barrow" ${wide?'style="grid-template-columns:85px 1fr 110px"':''}><span>${esc(k)}</span><div class="bartrack"><div class="bar" style="width:${n?Math.max(6,n/max*100):0}%"></div></div><b>${label??n}</b></div>`).join('')||'<p class="muted">尚無資料。</p>'}</div>`;}
function bindOpen(v){v.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>detail(b.dataset.open,b.dataset.id));}
function modal(html){const m=$('#modal');m.innerHTML=html;if(!m.open)m.showModal();m.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>m.close());return m;}
const MEETING_HOST=['opportunities','projects'];
function meetingsFor(type,r){const ids=new Set([r.id,type==='projects'?r.sourceOpportunityId:null].filter(Boolean));return data.meetings.filter(m=>ids.has(m.opportunityId)||ids.has(m.projectId)).sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.updatedAt).localeCompare(String(a.updatedAt)));}
function renderMeetingNotes(type,r){const box=$('#meetingnotes');if(!box)return;const list=meetingsFor(type,r),parts=[['transcript','會議紀錄全文'],['decisions','決議'],['changes','變更'],['risks','風險'],['todos','待辦']];
 box.innerHTML=`<div class="modalhead" style="margin-bottom:12px"><h2 style="margin:0">會議記錄 <small>(${list.length})</small></h2>${write()?'<button id="addmeetingnote" class="primary">＋ 新增會議記錄</button>':''}</div>${list.map((m,i)=>`<details class="meetingnote" ${i===0?'open':''}><summary><strong>${esc(m.date)}</strong> · ${esc(m.name)}${m.attendees?` <small>｜與會：${esc(m.attendees)}</small>`:''}</summary>${m.summary?`<p class="detailvalue">${esc(m.summary)}</p>`:''}${parts.filter(([k])=>m[k]).map(([k,l])=>`<div class="meetingpart"><small>${l}</small><div class="detailvalue">${esc(m[k])}</div></div>`).join('')}<div class="buttons" style="margin-top:10px"><button data-meeting-open="${m.id}">查看完整頁面</button>${write()?`<button data-meeting-edit="${m.id}">編輯</button>`:''}</div><small class="muted">版本 ${m.version} · 更新 ${new Date(m.updatedAt).toLocaleString('zh-TW')}</small></details>`).join('')||'<p class="muted">尚無會議記錄。每次開會或有重要更新，都可以在這裡新增一筆，內容可直接貼上整份會議紀錄。</p>'}`;
 const add=$('#addmeetingnote');if(add)add.onclick=()=>edit('meetings',{companyId:r.companyId,opportunityId:type==='opportunities'?r.id:r.sourceOpportunityId||'',projectId:type==='projects'?r.id:'',ownerId:user.id,date:today()});
 box.querySelectorAll('[data-meeting-open]').forEach(b=>b.onclick=()=>detail('meetings',b.dataset.meetingOpen));
 box.querySelectorAll('[data-meeting-edit]').forEach(b=>b.onclick=()=>edit('meetings',recordOf('meetings',b.dataset.meetingEdit)));}
function detail(type,id){const r=recordOf(type,id);if(!r)return toast('找不到資料');const fields=data.meta.fields[type];
 const m=modal(`<div class="modalhead"><h2>${esc(r.name)}</h2><button data-close aria-label="關閉">×</button></div><div class="buttons">${write()?`<button id="editrecord" class="primary">編輯${entityLabels[type]}</button>`:''}${type==='opportunities'&&r.outcome==='成交'&&write()?'<button id="convert">成交轉專案 →</button>':''}${type==='companies'&&write()?'<button id="addcontact">＋ 聯絡人</button>':''}${type==='meetings'&&write()?'<button id="meetingtask">＋ 建立會議待辦草稿</button>':''}${extraButtons(type,r)}${user.role==='admin'?'<button class="danger" id="deleterecord">移入垃圾桶</button>':''}</div><p><small>版本 ${r.version} · 更新 ${new Date(r.updatedAt).toLocaleString('zh-TW')}</small></p><div class="details">${Object.entries(fields).filter(([k])=>r[k]).map(([k,label])=>`<div><small>${esc(label.replace('*',''))}</small><div class="detailvalue">${esc(refType(k)?nameOf(refType(k),r[k]):r[k])}</div></div>`).join('')}</div>${type==='files'?`<p><a href="/api/files/${r.id}/download">下載檔案 (${Math.ceil(r.size/1024)} KB)</a></p>`:''}${MEETING_HOST.includes(type)?'<div id="meetingnotes" class="related"></div>':''}<div id="extra"></div><div id="related" class="related"></div>`);
 extraDetail(type,r,m);
 if(MEETING_HOST.includes(type))renderMeetingNotes(type,r);
 if($('#editrecord'))$('#editrecord').onclick=()=>edit(type,r);
 if($('#addcontact'))$('#addcontact').onclick=()=>edit('contacts',{companyId:r.id});
 if($('#meetingtask'))$('#meetingtask').onclick=()=>draftForm({kind:'create_task',data:{name:r.name+'：待辦',projectId:r.projectId,opportunityId:r.opportunityId,ownerId:r.ownerId,description:r.todos}});
 if($('#convert'))$('#convert').onclick=async e=>{e.target.disabled=true;try{const p=await api(`/api/opportunities/${id}/convert`,{method:'POST',body:{}});await refresh();detail('projects',p.id);toast('專案與產品里程碑已準備完成');}catch(e){toast(e.message);e.target.disabled=false;}};
 if($('#deleterecord'))$('#deleterecord').onclick=()=>deleteForm(type,r);
 let related=[];for(const t of Object.keys(data.meta.fields))for(const x of data[t]||[])if(t!==type&&!(t==='meetings'&&MEETING_HOST.includes(type))&&['companyId','opportunityId','projectId','visitId','meetingId','instrumentId','contractId','ticketId','productId','contactId'].some(k=>x[k]===id))related.push({type:t,record:x});
 $('#related').innerHTML=`<h2>關聯資料與歷史 <small>(${related.length})</small></h2>${related.map(({type:t,record:x})=>`<div class="row" data-open="${t}" data-id="${x.id}"><span class="badge">${entityLabels[t]}</span><div class="rowbody"><strong>${esc(x.name)}</strong><small>${esc([x.quoteNo,x.kind,x.model,x.stage,x.scheduledDate||x.date||x.quoteDate,t==='stockmoves'?(signedQty(x)>0?'+':'')+signedQty(x):''].filter(Boolean).join(' · '))}</small></div><span>→</span></div>`).join('')||'<p class="muted">尚無關聯紀錄。</p>'}${write()&&['companies','opportunities','projects','visits','meetings','instruments','contracts','tickets','products'].includes(type)?`<div class="buttons" style="margin-top:15px">${({companies:['instruments','tickets','quotes','contracts','visits','meetings','opportunities'],projects:['milestones','tasks','visits','files'],instruments:['tickets','contracts'],contracts:['tickets'],tickets:['stockmoves'],products:['stockmoves']}[type]||['tasks','visits','files']).map(t=>`<button data-related-add="${t}">＋ ${entityLabels[t]}</button>`).join('')}</div>`:''}`;bindOpen($('#related'));
 m.querySelectorAll('[data-related-add]').forEach(b=>b.onclick=()=>{const initial={};if(type==='companies')initial.companyId=id;else {if(r.companyId)initial.companyId=r.companyId;initial[{opportunities:'opportunityId',projects:'projectId',visits:'visitId',meetings:'meetingId',instruments:'instrumentId',contracts:'contractId',tickets:'ticketId',products:'productId'}[type]]=id;if(['visits','meetings'].includes(type)){initial.opportunityId=r.opportunityId;initial.projectId=r.projectId;}if(type==='contracts')initial.instrumentId=r.instrumentId;if(['tickets','products'].includes(type)&&b.dataset.relatedAdd==='stockmoves'){initial.kind=type==='tickets'?'維修領用':'國內進貨';delete initial.companyId;}}edit(b.dataset.relatedAdd,initial);});
}
function refType(k){return {companyId:'companies',ownerId:'users',leadOwnerId:'users',opportunityId:'opportunities',projectId:'projects',visitId:'visits',meetingId:'meetings',instrumentId:'instruments',contractId:'contracts',ticketId:'tickets',productId:'products',contactId:'contacts'}[k];}
const LONG=['notes','needs','risks','description','discussion','nextStep','lossReason','transcript','summary','decisions','changes','todos','symptom','diagnosis','partsUsed','calibration','items','terms','solution','content','includes','billingTerms'];
const MIC=['discussion','transcript','summary','symptom','diagnosis','notes'];
const GROUPISH=['groups','targetGroups','excludeGroups'];
const MODELS=['Phenom Pure G6','Phenom ProX G6','Phenom XL G2','Phenom Pharos G2','Phenom ProX G5','Phenom XL','Phenom Pharos'];
function optionList(type,k){const o=data.meta.options[k];return Array.isArray(o)?o:o?.[type];}
function fieldHTML(type,k,label,r){const required=label.endsWith('*'),value=r[k]??'',ref=refType(k);let options;
 if(ref)options=data[ref].filter(x=>!r.companyId||!x.companyId||x.companyId===r.companyId).map(x=>[x.id,ref==='products'?`${x.sku}｜${x.name}（庫存 ${stockOf(x.id)}）`:ref==='tickets'?`${x.name}（${x.stage}）`:x.name,x.companyId||'']);
 else if(k==='product')options=data.meta.products.map(x=>[x,x]);
 else if(k==='stage')options=(data.meta.stages[type]||[]).map(x=>[x,x]);
 else if(k==='outcome')options=[['成交','成交'],['未成交','未成交']];
 else if(k==='priority')options=['高','中','低'].map(x=>[x,x]);
 else if(k==='method')options=['實體拜訪','線上會議','電話','Email','其他'].map(x=>[x,x]);
 else if(optionList(type,k)&&!data.meta.multi.includes(k))options=optionList(type,k).map(x=>[x,x]);
 const long=LONG.includes(k);
 const inputType=k==='email'||k==='senderEmail'?'email':k==='website'?'url':data.meta.numbers.includes(k)?'number':['followUpAt','sendAt'].includes(k)?'datetime-local':k==='date'||k.endsWith('Date')?'date':'text';
 let element;
 if(data.meta.multi.includes(k)){const chosen=splitList(value);element=`<div class="checks">${optionList(type,k).map(o=>`<label><input type="checkbox" name="multi_${k}" value="${esc(o)}" ${chosen.includes(o)?'checked':''}>${esc(o)}</label>`).join('')}</div>`;}
 else if(k==='quoteNo')element=`<input name="${k}" value="${esc(value)}" readonly placeholder="保存後自動產生">`;
 else if(GROUPISH.includes(k)){const groups=[...new Set(data.contacts.flatMap(c=>splitList(c.groups)))];element=`<input name="${k}" value="${esc(value)}" placeholder="例如：SEM 用戶、學術單位"><div class="chips">${groups.map(g=>`<button type="button" class="chip" data-chip="${k}" data-value="${esc(g)}">＋${esc(g)}</button>`).join('')}</div>`;}
 else if(options)element=`<select name="${k}" ${required?'required':''}><option value="">請選擇</option>${options.map(([id,n,co])=>`<option value="${esc(id)}" ${co?`data-company="${esc(co)}"`:''} ${String(value)===id?'selected':''}>${esc(n)}</option>`).join('')}</select>`;
 else if(long)element=`<textarea name="${k}" ${required?'required':''} ${k==='items'?'placeholder="每行一個品項：品名 | 數量 | 單位 | 單價&#10;例：CeB6 燈絲 | 1 | EA | 38000"':''}>${esc(value)}</textarea>`;
 else element=`<input name="${k}" type="${inputType}" value="${esc(value)}" ${required?'required':''} ${inputType==='number'?`${k==='qty'?'':'min="0"'} ${k==='probability'?'max="100"':'step="any"'}`:''} ${k==='model'?'list="models"':''}>${k==='model'?`<datalist id="models">${MODELS.map(m=>`<option value="${m}">`).join('')}</datalist>`:''}`;
 return `<label class="field ${long||data.meta.multi.includes(k)?'wide':''}"><span class="fieldhead">${esc(label)}${MIC.includes(k)?`<button type="button" class="mic" data-mic="${k}">🎤 語音輸入</button>`:''}</span>${element}${k==='items'?'<small>系統會自動計算小計、5% 營業稅與合計；議價後金額填在下方欄位。</small>':''}${k==='qty'?'<small>盤點調整可填負數；其他類型填正數，系統依類型自動加減。</small>':''}</label>`;
}
function edit(type,initial={}){
 const r={ownerId:user.id,kind:type==='tickets'?'叫修':undefined,leadOwnerId:type==='contacts'?user.id:undefined,stage:data.meta.stages[type]?.[0]||'待辦',priority:'中',date:today(),quoteDate:type==='quotes'?today():undefined,inquiryDate:type==='contacts'?today():undefined,validDays:type==='quotes'?'30':undefined,subscription:type==='contacts'?'訂閱中':undefined,...initial};
 const fields=Object.entries(data.meta.fields[type]).map(([k,l])=>fieldHTML(type,k,l,r)).join('');
 const m=modal(`<div class="modalhead"><h2>${r.id?'編輯':'新增'}${entityLabels[type]}</h2><button data-close aria-label="關閉">×</button></div><form id="recordform"><div class="formgrid">${type==='opportunities'?companyQuickHTML():''}${type==='companies'&&!r.id?companyLookupHTML():''}${fields}${type==='files'&&!r.id?'<label class="field wide">上傳檔案*<input type="file" name="upload" required><small>本機上限 5 MB／雲端上限 3 MB。</small></label>':''}</div>${type==='opportunities'&&!r.id?'<div class="drafttools"><small>未送出內容會暫存在此分頁，保存後清除。</small><button type="button" id="restoredraft">還原未送出草稿</button></div>':''}<p class="error" id="formerror" role="alert"></p><div class="formfooter"><button type="button" data-close>取消</button><button class="primary" id="saverecord">保存</button></div></form>`);
 const form=$('#recordform'),quick=type==='opportunities'?initQuickCompany(form):null,draftKey='microcrm:opportunity:'+user.id;if(type==='companies'&&!r.id)initCompanyLookup(form);
 if(type==='opportunities'&&!r.id){form.addEventListener('input',()=>{try{sessionStorage.setItem(draftKey,JSON.stringify({fields:Object.fromEntries(new FormData(form)),isNew:quick.isNew()}));}catch{}});$('#restoredraft').onclick=()=>{try{const saved=JSON.parse(sessionStorage.getItem(draftKey));if(!saved)return toast('此分頁沒有未送出草稿');quick.mode(saved.isNew);for(const [key,value]of Object.entries(saved.fields))if(form.elements[key]&&form.elements[key].type!=='file')form.elements[key].value=value;toast('草稿已還原，請檢查後保存');}catch{toast('無法還原草稿');}};}
 form.onsubmit=async e=>{e.preventDefault();const button=$('#saverecord');button.disabled=true;$('#formerror').textContent='';try{const fd=new FormData(form),b=Object.fromEntries(fd);delete b.upload;for(const k of data.meta.multi)if(form.querySelector(`[name="multi_${k}"]`))b[k]=fd.getAll('multi_'+k).join('、');for(const key of Object.keys(b))if(key.startsWith('quick_')||key.startsWith('contact_')||key.startsWith('multi_'))delete b[key];delete b.quoteNo;
  if(quick?.isNew()){const saved=await api('/api/opportunities/quick-create',{method:'POST',body:{company:quick.company(),contact:quick.contact(),opportunity:b,id:r.id,version:r.version}});toast(saved.reused?'商機已保存，沿用既有公司資料':'公司、聯絡人與商機已一起保存');}
  else if(type==='files'&&!r.id){const file=form.upload.files[0];if(file.size>(data.meta.uploadLimitMb||5)*1024*1024)throw new Error('檔案上限 '+(data.meta.uploadLimitMb||5)+' MB');b.name=b.name||file.name;b.content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('無法讀取檔案'));reader.readAsDataURL(file);});await api('/api/uploads',{method:'POST',body:b});}
  else await api(`/api/records/${type}${r.id?'/'+r.id:''}`,{method:r.id?'PATCH':'POST',body:{...b,version:r.version}});
  if(type==='opportunities'&&!r.id)try{sessionStorage.removeItem(draftKey);}catch{}m.close();await refresh();if(!quick?.isNew())toast('資料已保存');
 }catch(e){if($('#formerror'))$('#formerror').textContent=e.message;button.disabled=false;}};
 bindMic(form);const co=form.elements.companyId;if(co&&co.tagName==='SELECT')co.addEventListener('change',()=>{for(const sel of form.querySelectorAll('select'))if(sel!==co)for(const o of sel.options)if(o.dataset.company){o.hidden=!!co.value&&o.dataset.company!==co.value;if(o.hidden&&o.selected)sel.value='';}});form.querySelectorAll('[data-chip]').forEach(c=>c.onclick=()=>{const input=form.elements[c.dataset.chip],list=splitList(input.value);if(!list.includes(c.dataset.value))input.value=[...list,c.dataset.value].join('、');});
 if(form.upload)form.upload.onchange=()=>{if(!form.elements.name.value)form.elements.name.value=form.upload.files[0]?.name||'';};
}

function deleteForm(type,r){const days=data.meta.trashDays||90;const m=modal(`<div class="modalhead"><h2>移入垃圾桶</h2><button data-close>×</button></div><p>將「${esc(r.name)}」移入垃圾桶。其下的關聯資料會一併移入；${days} 天內可在「垃圾桶」還原，期滿後永久刪除。</p><p class="error" id="deleteerror"></p><div class="formfooter"><button data-close>取消</button><button id="deleteconfirm" class="danger">移入垃圾桶</button></div>`);$('#deleteconfirm').onclick=async e=>{e.target.disabled=true;try{const b=await api(`/api/records/${type}/${r.id}`,{method:'DELETE',body:{version:r.version}});m.close();await refresh();toast('已移入垃圾桶'+(b.moved>1?'（含關聯資料共 '+b.moved+' 筆）':'')+'，'+days+' 天內可還原');}catch(err){$('#deleteerror').textContent=err.message;e.target.disabled=false;}};}
async function trashView(v){
 v.innerHTML='<p class="muted">載入中…</p>';
 try{
  const items=await api('/api/trash');
  v.innerHTML=`<p class="filehint">刪除的資料會先放在這裡，${data.meta.trashDays||90} 天內可以還原；期滿後會連同其關聯資料一併永久移除。</p><div class="tablewrap"><table><thead><tr><th>類型</th><th>名稱</th><th>刪除時間</th><th>預定永久移除</th><th>含關聯資料</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td>${esc(entityLabels[i.type]||i.type)}</td><td>${esc(i.name)}</td><td>${esc(new Date(i.deletedAt).toLocaleString('zh-TW'))}</td><td>${esc(new Date(i.purgeAt).toLocaleDateString('zh-TW'))}</td><td>${i.count>1?'共 '+i.count+' 筆':'—'}</td><td><button data-restore="${esc(i.type)}:${esc(i.id)}">還原</button> <button class="danger" data-purge="${esc(i.type)}:${esc(i.id)}">永久刪除</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">垃圾桶是空的。</td></tr>'}</tbody></table></div>`;
  v.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{const [type,id]=b.dataset.restore.split(':');b.disabled=true;try{const r=await api('/api/trash/restore',{method:'POST',body:{type,id}});await refresh();toast('已還原（共 '+r.restored+' 筆）');}catch(e){toast(e.message);b.disabled=false;}});
  v.querySelectorAll('[data-purge]').forEach(b=>b.onclick=()=>{const [type,id]=b.dataset.purge.split(':');purgeForm(items.find(i=>i.type===type&&i.id===id));});
 }catch(e){v.innerHTML='<p class="error">'+esc(e.message)+'</p>';}
}
function purgeForm(item){const m=modal(`<div class="modalhead"><h2>永久刪除</h2><button data-close>×</button></div><p>將永久刪除「${esc(item.name)}」${item.count>1?'及其關聯資料（共 '+item.count+' 筆）':''}，之後無法還原。</p><p class="error" id="purgeerror"></p><div class="formfooter"><button data-close>取消</button><button id="purgeconfirm" class="danger">永久刪除</button></div>`);$('#purgeconfirm').onclick=async e=>{e.target.disabled=true;try{await api('/api/trash/purge',{method:'POST',body:{type:item.type,id:item.id}});m.close();await refresh();toast('已永久刪除');}catch(err){$('#purgeerror').textContent=err.message;e.target.disabled=false;}};}
async function showSearch(q){try{const results=await api('/api/search?q='+encodeURIComponent(q));const m=modal(`<div class="modalhead"><h2>搜尋：${esc(q)}</h2><button data-close>×</button></div><p class="muted">${results.length} 筆結果（最多 100 筆）</p>${results.map(({entity,record:r})=>`<button class="searchresult" data-open="${entity}" data-id="${r.id}"><span class="badge">${entityLabels[entity]}</span> ${esc(r.name)}<small>${esc(String(r.summary||r.discussion||r.description||r.notes||r.needs||r.extractedText||'').slice(0,140))}</small></button>`).join('')||'<p class="empty">沒有找到結果，請改用較短關鍵字。</p>'}`);bindOpen(m);}catch(e){toast(e.message);}}
function draftForm(initial={}){const m=modal(`<div class="modalhead"><h2>建立寫入草稿</h2><button data-close>×</button></div><p class="muted">先保存為草稿；請在右側助理檢視後確認，才會寫入。</p><label class="field selection">操作<select id="draftkind"><option value="create_task">建立任務</option><option value="update_stage">更新商機階段</option><option value="project_stage">更新專案階段</option></select></label><form id="draftform"><div id="draftfields" class="formgrid"></div><p class="error" id="drafterror"></p><div class="formfooter"><button class="primary">產生草稿</button></div></form>`);
 const renderFields=()=>{const kind=$('#draftkind').value;if(kind==='create_task')$('#draftfields').innerHTML=Object.entries(data.meta.fields.tasks).filter(([k])=>!['stage','priority'].includes(k)).map(([k,l])=>fieldHTML('tasks',k,l,{ownerId:user.id,...initial.data})).join('');else{const type=kind==='project_stage'?'projects':'opportunities';$('#draftfields').innerHTML=`<label class="field wide">${entityLabels[type]}*<select name="id" required><option value="">請選擇</option>${data[type].map(r=>`<option value="${r.id}">${esc(r.name)}（${r.stage}）</option>`).join('')}</select></label>${fieldHTML(type,'stage','新階段*',{})}${type==='opportunities'?fieldHTML(type,'outcome','結案結果',{})+fieldHTML(type,'lossReason','未成交原因',{}):''}`;}};
 $('#draftkind').onchange=renderFields;renderFields();$('#draftform').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target)),kind=$('#draftkind').value;const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/drafts',{method:'POST',body:kind==='create_task'?{kind,data:{...b,stage:'待辦',priority:'中'}}:{kind:'update_stage',entity:kind==='project_stage'?'projects':'opportunities',...b}});m.close();aiVisible=true;await refresh();toast('草稿已建立，等待確認');}catch(e){$('#drafterror').textContent=e.message;button.disabled=false;}};
}
function settings(v){v.innerHTML=`<div class="settinggrid">${user.role==='admin'?adminCards():''}<div class="card"><h2>帳號與 AI 設定</h2><p>${esc(user.email)} · ${{admin:'管理員',member:'協作成員',viewer:'唯讀'}[user.role]}</p><p class="muted">目前 AI：${data.meta.mode==='demo'?'規則查詢模式（未設定 AI 金鑰）':'OpenAI API 模式'}。管理員可在部署環境設定 AI 服務，本機修改 .env 後重啟；Vercel 修改環境變數後重新部署。</p><button id="password">修改我的密碼</button></div>${user.role==='admin'?`<div class="card"><h2>團隊權限</h2><p class="muted">管理員：管理資料、帳號與刪除；協作成員：查閱、新增、編輯；唯讀：查閱與詢問。此 MVP 為單一團隊共用資料。</p><div class="tablewrap"><table><thead><tr><th>姓名</th><th>Email</th><th>角色</th></tr></thead><tbody>${data.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><select data-role="${u.id}" ${u.id===user.id?'disabled':''}>${[['admin','管理員'],['member','協作成員'],['viewer','唯讀']].map(([r,l])=>`<option value="${r}" ${r===u.role?'selected':''}>${l}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div><p><button id="adduser" class="primary">＋ 新增帳號</button></p></div><div class="card"><h2>操作審計 <small>最近 200 筆</small></h2><div class="tablewrap"><table><thead><tr><th>時間／執行者</th><th>操作</th><th>紀錄</th><th>前後內容</th></tr></thead><tbody>${data.audit.map(a=>`<tr><td>${esc(new Date(a.createdAt).toLocaleString('zh-TW'))}<br>${esc(a.actor)}</td><td>${esc(a.action)}</td><td>${esc(entityLabels[a.entity]||a.entity)}<br><small>${esc(a.recordId)}</small></td><td><details><summary>檢視</summary><pre class="auditbody">${esc('修改前：'+pretty(a.before)+'\n\n修改後：'+pretty(a.after))}</pre></details></td></tr>`).join('')}</tbody></table></div></div>`:''}<div class="card"><h2>四產品里程碑範本</h2>${Object.entries(data.meta.templates).map(([p,ms])=>`<p><strong>${esc(p)}</strong><br><small>${ms.map(esc).join(' → ')}</small></p>`).join('')}<p class="muted">成交轉專案時自動套用；各專案可編輯里程碑內容與預定完成日。</p></div><div class="card"><h2>草稿歷史</h2>${data.drafts.map(d=>`<details><summary>${esc(new Date(d.createdAt).toLocaleString('zh-TW'))} · ${esc(d.status)}</summary><pre class="auditbody">${esc(draftDescription(d.payload))}</pre></details>`).join('')||'<p class="muted">尚無草稿。</p>'}</div></div>`;
 bindAdminCards(v);$('#password').onclick=()=>accountForm(false);if($('#adduser'))$('#adduser').onclick=()=>accountForm(true);
 v.querySelectorAll('[data-role]').forEach(s=>s.onchange=async()=>{s.disabled=true;try{await api('/api/users/'+s.dataset.role,{method:'PATCH',body:{role:s.value}});await refresh();toast('角色已更新，該帳號需重新登入');}catch(e){toast(e.message);await refresh();}});
}
function pretty(v){try{return JSON.stringify(JSON.parse(v),null,2);}catch{return v;}}
function accountForm(create){const m=modal(`<div class="modalhead"><h2>${create?'新增團隊帳號':'修改密碼'}</h2><button data-close>×</button></div><form id="accountform"><div class="formgrid">${create?'<label class="field">姓名<input name="name" required maxlength="100"></label><label class="field">Email<input type="email" name="email" required></label><label class="field">角色<select name="role"><option value="member">協作成員</option><option value="viewer">唯讀</option><option value="admin">管理員</option></select></label>':'<label class="field wide">原密碼<input name="current" type="password" autocomplete="current-password" required></label>'}<label class="field wide">${create?'登入密碼':'新密碼'}（12–200 字元）<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="200" required></label></div><p class="error" id="accounterror"></p><div class="formfooter"><button class="primary">保存</button></div></form>`);$('#accountform').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api(create?'/api/users':'/api/password',{method:'POST',body:Object.fromEntries(new FormData(e.target))});m.close();await refresh();toast('已保存');}catch(e){$('#accounterror').textContent=e.message;b.disabled=false;}};}
(async()=>{try{const b=await api('/api/me');user=b.user;csrf=b.csrf;await refresh();}catch{login();}})();





function showChangelog(){const log=window.CHANGELOG||[];modal(`<div class="modalhead"><h2>版本紀錄</h2><button data-close>關閉</button></div>${log.map((v,i)=>`<div class="related" style="${i?'':'border-top:0;margin-top:0;padding-top:0'}"><h3>V${esc(v.version)} <span class="badge${i?'':' green'}">${esc(v.type)}${i?'':'・目前版本'}</span> <small>${esc(v.date)}</small></h3><ul>${v.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>`).join('')}`);}

// ======================= Cross-department modules =======================
function dashboard(v){
 const yr=String(new Date().getFullYear()),won=data.quotes.filter(q=>q.stage==='成交'&&String(q.quoteDate).startsWith(yr));
 const openT=data.tickets.filter(t=>t.stage!=='已完工'),expiring=data.contracts.filter(c=>{const d=daysTo(c.endDate);return d>=0&&d<=60;});
 const pmDue=data.tickets.filter(t=>t.kind==='PM 巡檢'&&t.stage!=='已完工'&&daysTo(t.scheduledDate)<=30),low=data.products.filter(isLow);
 const fixed=data.tickets.filter(t=>t.kind==='叫修'&&t.stage==='已完工'&&t.completedDate);const mttr=fixed.length?(fixed.reduce((a,t)=>a+Math.max(0,(Date.parse(t.completedDate)-Date.parse(t.scheduledDate||t.createdAt.slice(0,10)))/86400000),0)/fixed.length).toFixed(1):'—';
 const leads=data.contacts.filter(c=>c.channel||c.leadStatus),openO=data.opportunities.filter(o=>o.stage!=='結案');
 const sum=a=>a.reduce((n,q)=>n+quoteTotals(q).net,0);
 const kpi={
  '全部':[['今年成交金額','NT$ '+money(sum(won)),won.length+' 張成交報價','＄'],['處理中工單',openT.length,openT.filter(t=>t.priority==='高').length+' 張急件','⚒'],['60 天內到期合約',expiring.length,'請安排續約','▣'],['低於安全庫存',low.length,'個料號需補貨','▥']],
  '業務':[['進行中商機',openO.length,'筆商機','◫'],['報價追蹤中',data.quotes.filter(q=>['報價中','議價中'].includes(q.stage)).length,'張報價單','＄'],['今年成交金額','NT$ '+money(sum(won)),won.length+' 張','↗'],['60 天內到期合約',expiring.length,'續約商機','▣']],
  '行銷':[['名單總數',leads.length,'筆名單','☷'],['有效名單',leads.filter(c=>c.leadStatus==='有效名單').length,'筆','✓'],['本月新增',leads.filter(c=>String(c.inquiryDate).slice(0,7)===today().slice(0,7)).length,'筆名單','↗'],['已取消訂閱',data.contacts.filter(c=>c.subscription==='已取消訂閱').length,'自動排除寄送','✉']],
  '維修':[['處理中工單',openT.length,openT.filter(t=>t.stage==='待料').length+' 張待料','⚒'],['30 天內 PM',pmDue.length,'張預防保養工單','▣'],['平均修復天數 MTTR',mttr,'叫修開單至完工','⏱'],['低於安全庫存',low.length,'個料號','▥']]
 };kpi['客服']=kpi['維修'];
 const stats=kpi[viewDept]||kpi['全部'];
 const ops=`<div class="split"><div class="card"><h2>維修工單狀態 <small style="float:right">${data.tickets.length} 張</small></h2>${bars(data.meta.stages.tickets.map(s=>[s,data.tickets.filter(t=>t.stage===s).length]))}</div><div class="card"><h2>即將到期合約 <small style="float:right">60 天內</small></h2>${expiring.sort((a,b)=>a.endDate.localeCompare(b.endDate)).map(c=>`<div class="row" data-open="contracts" data-id="${c.id}"><span class="badge high">${daysTo(c.endDate)} 天</span><div class="rowbody"><strong>${esc(c.name)}</strong><small>${esc(nameOf('companies',c.companyId))} · 負責 ${esc(nameOf('users',c.ownerId))}</small></div></div>`).join('')||'<p class="muted">近期沒有到期合約。</p>'}</div></div><div class="split"><div class="card"><h2>近期 PM 與預約到場</h2>${data.tickets.filter(t=>t.stage!=='已完工'&&t.scheduledDate).sort((a,b)=>a.scheduledDate.localeCompare(b.scheduledDate)).slice(0,5).map(t=>`<div class="row" data-open="tickets" data-id="${t.id}"><span class="badge ${t.priority==='高'?'high':''}">${esc(t.kind)}</span><div class="rowbody"><strong>${esc(t.name)}</strong><small>${esc(nameOf('companies',t.companyId))} · ${esc(nameOf('users',t.ownerId))}</small></div><small>${esc(t.scheduledDate)}</small></div>`).join('')||'<p class="muted">尚無排程。</p>'}</div><div class="card"><h2>庫存提醒</h2>${low.map(p=>`<div class="row" data-open="products" data-id="${p.id}"><span class="badge high">${stockOf(p.id)} / ${esc(p.safetyStock)}</span><div class="rowbody"><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${esc(p.category)}</small></div></div>`).join('')||'<p class="muted">所有料號皆高於安全庫存。</p>'}</div></div>`;
 const revenue=`<div class="split"><div class="card"><h2>${yr} 年成交業績（依類別，未稅）</h2>${bars((data.meta.options.category.quotes||[]).map(c=>{const n=sum(won.filter(q=>q.category===c));return [c,n,'NT$ '+money(n)];}))}</div><div class="card"><h2>待追蹤報價</h2>${data.quotes.filter(q=>['報價中','議價中'].includes(q.stage)).map(q=>`<div class="row" data-open="quotes" data-id="${q.id}"><span class="badge">${esc(q.stage)}</span><div class="rowbody"><strong>${esc(q.name)}</strong><small>${esc(q.quoteNo)} · ${esc(nameOf('companies',q.companyId))}</small></div><small>NT$ ${money(quoteTotals(q).net)}</small></div>`).join('')||'<p class="muted">沒有待追蹤報價。</p>'}</div></div>`;
 const mk=`<div class="split"><div class="card"><h2>名單來源（諮詢管道）</h2>${bars(Object.entries(countBy(leads,c=>[c.channel||'未填'])).sort((a,b)=>b[1]-a[1]))}</div><div class="card"><h2>諮詢產品</h2>${bars(Object.entries(countBy(leads,c=>splitList(c.interestProducts))).sort((a,b)=>b[1]-a[1]))}</div></div>`;
 const order={'業務':[revenue,'S'],'行銷':[mk],'維修':[ops],'客服':[ops,revenue],'全部':[revenue,ops,mk,'S']}[viewDept]||[revenue,ops,'S'];
 v.innerHTML=`${low.length&&['維修','客服','全部'].includes(viewDept)?`<div class="deadlinealert">⚑ ${low.length} 個料號低於安全庫存，請安排採購補貨。</div>`:''}<div class="stats">${stats.map(([title,value,note,icon])=>`<div class="stat"><span class="icon">${icon}</span><small>${title}</small><div class="value" style="${String(value).length>9?'font-size:22px':''}">${value}</div><small>${note}</small></div>`).join('')}</div>${order.map(x=>x==='S'?'<div id="salesdash"></div>':x).join('')}`;
 bindOpen(v);const sd=$('#salesdash');if(sd){salesDashboard(sd);sd.querySelector('.stats')?.remove();sd.querySelector('.deadlinealert')?.remove();}
}
function countBy(rows,fn){const m={};for(const r of rows)for(const k of fn(r))m[k]=(m[k]||0)+1;return m;}
function leadsView(v){
 const groups=[...new Set(data.contacts.flatMap(c=>splitList(c.groups)))];const [g,ch]=(filter||'|').split('|');
 const rows=data.contacts.filter(c=>(!g||splitList(c.groups).includes(g))&&(!ch||c.channel===ch));
 const oppStatus=c=>{const o=data.opportunities.filter(x=>x.companyId===c.companyId);const q=data.quotes.filter(x=>x.companyId===c.companyId);return o.length?o.map(x=>x.stage+(x.outcome?'・'+x.outcome:'')).join('、'):q.length?'報價：'+q.map(x=>x.stage).join('、'):'—';};
 v.innerHTML=`<div class="toolbar"><select id="lg"><option value="">全部分組</option>${groups.map(x=>`<option ${x===g?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="lc"><option value="">全部管道</option>${(data.meta.options.channel.contacts||[]).map(x=>`<option ${x===ch?'selected':''}>${esc(x)}</option>`).join('')}</select><span class="badge">${rows.length} 筆名單</span><button id="leadcsv">↓ 下載目前名單 CSV</button><small>同一名單可屬多個分組；取消訂閱者寄送 EDM 時自動排除。</small></div><div class="split"><div class="card"><h2>依管道</h2>${bars(Object.entries(countBy(rows,c=>[c.channel||'未填'])))}</div><div class="card"><h2>依名單認列</h2>${bars(Object.entries(countBy(rows,c=>[c.leadStatus||'未填'])))}</div></div><div class="tablewrap"><table><thead><tr><th>聯絡人</th><th>公司</th><th>諮詢日期</th><th>管道</th><th>認列</th><th>諮詢產品</th><th>分組</th><th>商機狀態</th><th>負責人</th><th>EDM</th></tr></thead><tbody>${rows.map(c=>`<tr><td><button class="link" data-open="contacts" data-id="${c.id}">${esc(c.name)}</button><small style="display:block">${esc(c.email||'')}</small></td><td>${esc(nameOf('companies',c.companyId))}</td><td>${esc(c.inquiryDate||'—')}</td><td>${esc(c.channel||'—')}</td><td>${esc(c.leadStatus||'—')}</td><td>${esc(c.interestProducts||'—')}</td><td>${splitList(c.groups).map(x=>`<span class="badge">${esc(x)}</span>`).join(' ')||'—'}</td><td>${esc(oppStatus(c))}</td><td>${esc(nameOf('users',c.leadOwnerId))}</td><td>${c.subscription==='已取消訂閱'?'<span class="badge high">已退訂</span>':'<span class="badge green">訂閱</span>'}</td></tr>`).join('')||'<tr><td colspan="10" class="empty">尚無名單。</td></tr>'}</tbody></table></div>`;
 bindOpen(v);$('#lg').onchange=$('#lc').onchange=()=>{filter=$('#lg').value+'|'+$('#lc').value;renderView();};
 $('#leadcsv').onclick=()=>{const cols=[['name','姓名'],['company','公司'],['email','Email'],['phone','電話'],['inquiryDate','諮詢日期'],['channel','諮詢管道'],['leadStatus','名單認列'],['interestProducts','諮詢產品'],['groups','分組'],['subscription','EDM 訂閱']];const q=x=>'"'+String(x??'').replace(/^[=+\-@\t\r]/,"'$&").replaceAll('"','""')+'"';const csv='﻿'+[cols.map(c=>q(c[1])).join(','),...rows.map(r=>cols.map(([k])=>q(k==='company'?nameOf('companies',r.companyId):r[k])).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='行銷名單.csv';a.click();};
}
function extraButtons(type,r){if(!write())return type==='quotes'?'<button id="printquote">🖨 列印報價單</button>':'';
 return {contracts:'<button id="schedulepm">⟳ 產生 PM 排程工單</button>',quotes:'<button id="printquote">🖨 列印報價單</button>',tickets:'<button id="printreport">🖨 維修報告</button><button id="askai">✦ AI 診斷建議</button>',campaigns:'<button id="testmail">✉ 寄送測試信</button>'}[type]||'';}
function extraDetail(type,r,m){const box=$('#extra');
 if(type==='tickets'){const st=data.meta.stages.tickets,idx=st.indexOf(r.stage),inst=recordOf('instruments',r.instrumentId);
  const words=s=>{const t=String(s||'').replace(/\s/g,'');const out=new Set();for(let i=0;i<t.length-1;i++)out.add(t.slice(i,i+2));return out;};const mine=words(r.symptom+r.name);
  const kb=data.articles.map(a=>({a,score:(r.errorCode&&a.errorCode&&a.errorCode.toLowerCase()===r.errorCode.toLowerCase()?100:0)+[...words(a.symptom+a.name)].filter(w=>mine.has(w)).length})).filter(x=>x.score>=3).sort((x,y)=>y.score-x.score).slice(0,3);
  const similar=data.tickets.filter(t=>t.id!==r.id&&((r.errorCode&&t.errorCode===r.errorCode)||(r.instrumentId&&t.instrumentId===r.instrumentId))).slice(0,5);
  const parts=data.stockmoves.filter(x=>x.ticketId===r.id);
  box.innerHTML=`<div class="related"><h2>維修進度（客戶可見）</h2><div class="stepper">${st.map((s,i)=>`<div class="${i<idx?'done':i===idx?'now':''}"><span>${i+1}</span>${esc(s)}</div>`).join('')}</div>${inst?`<p><small>儀器</small><br><b>${esc(inst.model)}</b>　序號 ${esc(inst.serialNo||'—')}　${esc(inst.warrantyStatus||'')}${inst.warrantyStatus==='過保'?' <span class="badge high">過保：需報價</span>':''}</p>`:''}</div><div class="related kbbox"><h2>✦ 知識庫建議 <small>${r.errorCode?'依錯誤代碼 '+esc(r.errorCode):'依症狀相似度'}</small></h2>${kb.map(({a})=>`<details class="meetingnote" open><summary><strong>${esc(a.errorCode||'')}</strong> ${esc(a.name)}</summary><div class="detailvalue">${esc(a.solution)}</div><small class="muted">${esc(a.source||'')}</small></details>`).join('')||'<p class="muted">知識庫中尚無對應 SOP，可在「知識庫」新增，下次會自動帶出。</p>'}<h3 style="margin-top:14px">過往相似案例</h3>${similar.map(t=>`<div class="row" data-open="tickets" data-id="${t.id}"><span class="badge">${esc(t.stage)}</span><div class="rowbody"><strong>${esc(t.name)}</strong><small>${esc(nameOf('companies',t.companyId))} · ${esc(t.diagnosis||t.symptom||'').slice(0,60)}</small></div></div>`).join('')||'<p class="muted">沒有相同錯誤代碼或同一儀器的歷史工單。</p>'}</div><div class="related"><h2>零件領用 <small>(${parts.length})</small></h2>${parts.map(x=>`<div class="row" data-open="stockmoves" data-id="${x.id}"><span class="badge">${esc(x.kind)}</span><div class="rowbody"><strong>${esc(nameOf('products',x.productId))}</strong><small>${esc(x.date)} · 數量 ${esc(x.qty)}</small></div></div>`).join('')||'<p class="muted">尚未領用零件。按下方「＋ 庫存異動」領料，系統會檢查機型相容性與庫存。</p>'}</div>`;
  bindOpen(box);
  if($('#printreport'))$('#printreport').onclick=()=>printReport(r);
  if($('#askai'))$('#askai').onclick=()=>{m.close();aiVisible=true;$('.ai').classList.add('visible');$('#chatform textarea').value=`請分析工單「${r.name}」（ID ${r.id}）：可能原因、建議攜帶的零件（確認庫存與機型相容）、處理步驟，並參考知識庫與同儀器維修史。`;$('#chatform').requestSubmit();};
 }
 if(type==='contracts'){const u=contractUsage(r),d=daysTo(r.endDate);
  box.innerHTML=`<div class="related"><h2>合約使用狀況</h2><div class="stats" style="grid-template-columns:repeat(3,1fr)"><div class="stat"><small>巡檢（已完成／合約）</small><div class="value">${u.pmDone} / ${esc(r.inspections||0)}</div><small>已排程 ${u.pmAll} 張</small></div><div class="stat"><small>叫修（已使用／合約）</small><div class="value">${u.callUsed} / ${esc(r.callouts||0)}</div><small>${u.callUsed>=Number(r.callouts||0)&&Number(r.callouts)>0?'已用完，後續叫修需報價':'仍有額度'}</small></div><div class="stat"><small>到期</small><div class="value" style="font-size:22px">${d<0?'已到期':d+' 天'}</div><small>${esc(r.endDate)}</small></div></div>${d>=0&&d<=60?'<div class="deadlinealert">⚑ 合約即將到期，建議業務聯繫客戶續約（可在報價單建立續約報價）。</div>':''}</div>`;
  if($('#schedulepm'))$('#schedulepm').onclick=async e=>{e.target.disabled=true;try{const t=await api(`/api/contracts/${r.id}/schedule-pm`,{method:'POST',body:{}});await refresh();toast(`已依合約期間平均排定 ${t.length} 張 PM 巡檢工單`);detail('contracts',r.id);}catch(err){toast(err.message);e.target.disabled=false;}};
 }
 if(type==='quotes'){const t=quoteTotals(r);
  box.innerHTML=`<div class="related"><h2>報價明細 <small>${esc(r.quoteNo||'')}</small></h2><div class="tablewrap"><table><thead><tr><th>項次</th><th>品名說明</th><th>數量</th><th>單位</th><th>單價</th><th>金額</th></tr></thead><tbody>${t.lines.map((l,i)=>`<tr><td>${i+1}</td><td>${esc(l.name)}</td><td>${l.qty}</td><td>${esc(l.unit)}</td><td>${l.price?money(l.price):''}</td><td>${l.amount?money(l.amount):''}</td></tr>`).join('')}</tbody></table></div><p style="text-align:right">小計 NT$ ${money(t.subtotal)}${t.net!==t.subtotal?`　議價後 <b>NT$ ${money(t.net)}</b>`:''}　營業稅 NT$ ${money(t.tax)}　<b>合計 NT$ ${money(t.total)}</b></p></div>`;
  if($('#printquote'))$('#printquote').onclick=()=>printQuote(r);
 }
 if(type==='products'){const n=stockOf(r.id);box.innerHTML=`<div class="related"><div class="stats" style="grid-template-columns:repeat(3,1fr)"><div class="stat"><small>目前庫存</small><div class="value">${n}</div><small>${esc(r.unit||'')}</small></div><div class="stat"><small>安全庫存</small><div class="value">${esc(r.safetyStock||0)}</div><small>${isLow(r)?'⚑ 低於安全庫存':'正常'}</small></div><div class="stat"><small>適用機型</small><div class="value" style="font-size:14px">${esc(r.compatibleModels||'通用')}</div></div></div></div>`;}
 if(type==='instruments'){const t=data.tickets.filter(x=>x.instrumentId===r.id),c=data.contracts.filter(x=>x.instrumentId===r.id&&daysTo(x.endDate)>=0);box.innerHTML=`<div class="related"><h2>儀器數位身分證</h2><div class="stats" style="grid-template-columns:repeat(3,1fr)"><div class="stat"><small>維修／保養紀錄</small><div class="value">${t.length}</div><small>${t.filter(x=>x.stage!=='已完工').length} 張處理中</small></div><div class="stat"><small>有效合約</small><div class="value">${c.length}</div><small>${esc(c[0]?.name||'無')}</small></div><div class="stat"><small>更換零件次數</small><div class="value">${data.stockmoves.filter(m=>t.some(x=>x.id===m.ticketId)).length}</div><small>依工單領料</small></div></div></div>`;}
 if(type==='campaigns'){const rc=recipientsOf(r),d=Number(r.delivered)||0;
  box.innerHTML=`<div class="related"><h2>收件人 <small>${rc.length} 位（已排除取消訂閱與排除分組）</small></h2><p class="muted">${rc.map(c=>esc(c.name)).join('、')||'目前分組沒有符合的收件人'}</p>${d?`<h2>成效</h2><div class="stats" style="grid-template-columns:repeat(5,1fr)">${[['成功遞送',r.delivered,''],['退回',r.bounced,pct(r.bounced,d)],['開啟',r.opened,pct(r.opened,d)],['點擊',r.clicked,pct(r.clicked,d)],['取消訂閱',r.unsubscribed,pct(r.unsubscribed,d)]].map(([k,n,p])=>`<div class="stat"><small>${k}</small><div class="value" style="font-size:22px">${esc(n||0)}</div><small>${p}</small></div>`).join('')}</div>`:''}<h2>預覽 <small>主旨 A${r.subjectB?' ／ B（A/B 測試）':''}</small></h2><div class="previews"><div class="preview desktop"><small>桌面版</small><div class="mail"><b>${esc(r.name)}</b>${r.subjectB?`<br><b class="muted">B：${esc(r.subjectB)}</b>`:''}<p class="muted">${esc(r.senderName||'')} &lt;${esc(r.senderEmail||'')}&gt; · ${esc(r.preheader||'')}</p><div class="detailvalue">${esc(r.content)}</div></div></div><div class="preview mobile"><small>行動版</small><div class="mail"><b>${esc(r.name)}</b><p class="muted">${esc(r.preheader||'')}</p><div class="detailvalue">${esc(r.content)}</div></div></div></div></div>`;
  if($('#testmail'))$('#testmail').onclick=()=>toast('展示版：測試信與正式寄送將串接寄信服務（如 Brevo／SendGrid），以追蹤遞送、開信與點擊。');
 }
}
function printDoc(title,body){const w=window.open('','_blank');if(!w)return toast('請允許彈出視窗以列印');w.document.write(`<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font:13px/1.6 "Microsoft JhengHei",sans-serif;color:#111;margin:28px}h1{text-align:center;letter-spacing:12px;font-size:22px;margin:14px 0}table{width:100%;border-collapse:collapse;margin:10px 0}td,th{border:1px solid #999;padding:6px 8px;vertical-align:top}th{background:#eee}.head{text-align:center}.head b{font-size:18px}.right{text-align:right}.sign{margin-top:40px;display:flex;justify-content:space-between}.pre{white-space:pre-wrap}@media print{button{display:none}}</style></head><body>${body}</body></html>`);w.document.close();setTimeout(()=>w.print(),300);}
function headerBlock(){const s=data.meta.settings;return `<div class="head"><b>${esc(s.quoteCompany)}</b><div class="pre">${esc(s.quoteHeader)}</div></div>`;}
function printQuote(r){const t=quoteTotals(r),c=recordOf('companies',r.companyId),p=recordOf('contacts',r.contactId),owner=data.users.find(u=>u.id===r.ownerId);
 printDoc(r.quoteNo||'報價單',`${headerBlock()}<h1>報價單</h1><table><tr><td>客戶名稱：${esc(c?.name||'')}</td><td>本單編號：${esc(r.quoteNo||'')}</td></tr><tr><td>聯絡人：${esc(p?.name||'')}</td><td>報價日期：${esc(r.quoteDate)}</td></tr><tr><td>聯絡電話：${esc(p?.phone||c?.phone||'')}</td><td>業　　務：${esc(owner?.name||'')}</td></tr><tr><td>E-Mail：${esc(p?.email||'')}</td><td>有效期限：${esc(r.validDays||30)} 天</td></tr></table><table><tr><th>項次</th><th>品名說明</th><th>數量</th><th>單位</th><th>單價</th><th>金額</th></tr>${t.lines.map((l,i)=>`<tr><td>${i+1}</td><td class="pre">${esc(l.name)}</td><td class="right">${l.qty}</td><td>${esc(l.unit)}</td><td class="right">${l.price?money(l.price):''}</td><td class="right">${l.amount?money(l.amount):''}</td></tr>`).join('')}<tr><td colspan="5" class="right">小計</td><td class="right">${money(t.subtotal)}</td></tr>${t.net!==t.subtotal?`<tr><td colspan="5" class="right">經雙方議價後優惠價（未稅）</td><td class="right">${money(t.net)}</td></tr>`:''}<tr><td colspan="5" class="right">營業稅 5%</td><td class="right">${money(t.tax)}</td></tr><tr><td colspan="5" class="right"><b>合計</b></td><td class="right"><b>${money(t.total)}</b></td></tr></table><p class="pre"><b>備註</b>\n交期：${esc(r.delivery||'—')}　付款方式：${esc(r.payment||'—')}\n${esc(r.terms||'')}\n${esc(data.meta.settings.quoteTerms)}</p><div class="sign"><span>報價人：${esc(owner?.name||'')}</span><span>客戶確認（簽章）：＿＿＿＿＿＿＿＿＿＿＿＿</span></div>`);}
function printReport(r){const c=recordOf('companies',r.companyId),i=recordOf('instruments',r.instrumentId),parts=data.stockmoves.filter(x=>x.ticketId===r.id);
 printDoc('維修服務報告',`${headerBlock()}<h1>維修服務報告</h1><table><tr><td>客戶：${esc(c?.name||'')}</td><td>工單：${esc(r.name)}</td></tr><tr><td>儀器：${esc(i?.model||'')}　序號：${esc(i?.serialNo||'')}</td><td>類型：${esc(r.kind)}　狀態：${esc(r.stage)}</td></tr><tr><td>到場日：${esc(r.scheduledDate||'')}</td><td>完工日：${esc(r.completedDate||'')}　工程師：${esc(nameOf('users',r.ownerId))}</td></tr></table><table><tr><th style="width:20%">項目</th><th>內容</th></tr><tr><td>故障描述</td><td class="pre">${esc(r.errorCode?'['+r.errorCode+'] ':'')}${esc(r.symptom)}</td></tr><tr><td>診斷與處理</td><td class="pre">${esc(r.diagnosis||'')}</td></tr><tr><td>更換零件</td><td class="pre">${parts.map(x=>esc(nameOf('products',x.productId))+' ×'+esc(x.qty)).join('\n')}${r.partsUsed?'\n'+esc(r.partsUsed):''}</td></tr><tr><td>校正數據</td><td class="pre">${esc(r.calibration||'')}</td></tr></table><div class="sign"><span>服務工程師：${esc(nameOf('users',r.ownerId))}</span><span>客戶簽收：${esc(r.signedBy||'＿＿＿＿＿＿＿＿＿＿')}</span></div>`);}
function bindMic(form){form.querySelectorAll('[data-mic]').forEach(b=>b.onclick=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return toast('此瀏覽器不支援語音輸入，請使用 Chrome 或 Edge');
 if(b._rec){b._rec.stop();return;}const rec=new SR();rec.lang='zh-TW';rec.continuous=true;rec.interimResults=false;const area=form.elements[b.dataset.mic];
 rec.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++)if(e.results[i].isFinal)area.value+=(area.value&&!area.value.endsWith('\n')?'，':'')+e.results[i][0].transcript;};
 rec.onend=()=>{b._rec=null;b.textContent='🎤 語音輸入';b.classList.remove('recording');};rec.onerror=e=>toast('語音輸入：'+(e.error==='not-allowed'?'請允許麥克風權限':e.error));
 rec.start();b._rec=rec;b.textContent='■ 停止錄音';b.classList.add('recording');});}

function adminCards(){const st=data.meta.settings,f=[['brandMark','系統標誌（短字，例如 KCT）'],['brandName','公司名稱'],['brandTagline','系統副標'],['quoteCompany','報價單抬頭公司名稱'],['quotePrefix','報價單號前綴（英數）'],['quoteHeader','報價單抬頭資訊（電話、地址、傳真、營業項目）'],['quoteTerms','報價單預設條款']];
 return `<div class="card"><h2>品牌與貼牌設定</h2><p class="muted">同一套系統核心，可依客戶更換名稱、標誌與報價單抬頭。</p><form id="brandform"><div class="formgrid">${f.map(([k,l])=>`<label class="field ${['quoteHeader','quoteTerms'].includes(k)?'wide':''}">${l}${['quoteHeader','quoteTerms'].includes(k)?`<textarea name="${k}">${esc(st[k])}</textarea>`:`<input name="${k}" value="${esc(st[k])}">`}</label>`).join('')}</div><div class="formfooter"><button class="primary">保存品牌設定</button></div></form></div>
 <div class="card"><h2>部門設定</h2><p class="muted">部門決定登入後的預設選單與 Dashboard；資料仍跨部門互通。管理員可在上方「部門視角」切換預覽。</p><div class="tablewrap"><table><thead><tr><th>姓名</th><th>Email</th><th>部門</th></tr></thead><tbody>${data.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td><select data-dept="${u.id}"><option value="">未設定</option>${data.meta.departments.map(d=>`<option ${u.department===d?'selected':''}>${d}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div></div>
 <div class="card"><h2>示範資料</h2><p class="muted">依客戶提供的 Excel 格式（維修業績、保養合約、耗材案件、庫存清單）建立一組標示「示範」的資料，用於展示跨部門流程。清除時只會刪除這組示範資料與掛在其下的紀錄，不影響其他資料。</p><div class="buttons">${data.meta.demoLoaded?'<button id="democlear" class="danger">清除示範資料</button>':'<button id="demoload" class="primary">載入示範資料</button>'}</div></div>`;}
function bindAdminCards(v){
 const bf=$('#brandform');if(bf)bf.onsubmit=async e=>{e.preventDefault();try{await api('/api/settings',{method:'POST',body:Object.fromEntries(new FormData(bf))});await refresh();toast('品牌設定已保存');}catch(err){toast(err.message);}};
 v.querySelectorAll('[data-dept]').forEach(sel=>sel.onchange=async()=>{if(!sel.value)return;try{await api(`/api/users/${sel.dataset.dept}/department`,{method:'POST',body:{department:sel.value}});await refresh();toast('部門已更新，該帳號下次載入時套用');}catch(e){toast(e.message);}});
 const load=$('#demoload');if(load)load.onclick=async()=>{load.disabled=true;try{const r=await api('/api/demo/load',{method:'POST',body:{}});await refresh();toast(`已載入 ${r.loaded} 筆示範資料`);}catch(e){toast(e.message);load.disabled=false;}};
 const clear=$('#democlear');if(clear)clear.onclick=()=>{const m=modal(`<div class="modalhead"><h2>清除示範資料</h2><button data-close>×</button></div><p>將永久刪除所有示範資料，以及在示範公司、儀器、工單底下新增的紀錄。此動作無法還原。</p><div class="formfooter"><button data-close>取消</button><button id="democonfirm" class="danger">永久清除</button></div>`);$('#democonfirm').onclick=async e=>{e.target.disabled=true;try{const r=await api('/api/demo/clear',{method:'POST',body:{}});m.close();await refresh();toast(`已清除 ${r.removed} 筆示範資料`);}catch(err){toast(err.message);e.target.disabled=false;}};};
}
